<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth;

use PDO;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\Gateway\DcrInitialAccessTokenCommandRepositoryGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\Tenant;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientQueryRepositoryGateway;
use Civi\Lughauth\Features\OAuth\Client\Domain\DcrInitialAccess;
use Civi\Lughauth\Features\OAuth\Client\Domain\Exception\DynamicClientException;
use Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven\DcrInitialAccessTokenSqlAdapter;
use Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven\TrustedClientFinder;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Security\SecretDigester;
use PHPUnit\Framework\TestCase;

/**
 * Initial access token verification and atomic consumption over MySQL (task 023).
 */
final class DcrInitialAccessTokenSqlAdapterTest extends TestCase
{
    private PDO $pdo;
    private string $tenantUid;
    private SecretDigester $digester;
    private DcrInitialAccessTokenSqlAdapter $adapter;
    /** @var string[] */
    private array $created = [];

    protected function setUp(): void
    {
        $this->pdo = $this->connect();
        $uid = $this->pdo->query('SELECT uid FROM access_tenant ORDER BY uid LIMIT 1')->fetchColumn();
        if (!is_string($uid)) {
            $this->markTestSkipped('No tenant on the integration database');
        }
        $this->tenantUid = $uid;
        $this->digester = new SecretDigester(['p1' => 'pepper-one'], 'p1');

        $tenants = $this->createStub(TenantQueryRepositoryGateway::class);
        $tenants->method('findOneByName')->willReturnCallback(function (string $name): ?Tenant {
            $uid = ['mine' => $this->tenantUid, 'other' => 'another-tenant-uid'][$name] ?? null;
            if ($uid === null) {
                return null;
            }
            $tenant = $this->createStub(Tenant::class);
            $tenant->method('uid')->willReturn($uid);
            return $tenant;
        });
        $finder = new TrustedClientFinder($this->createStub(TrustedClientQueryRepositoryGateway::class), $tenants);
        $this->adapter = new DcrInitialAccessTokenSqlAdapter(
            $this->pdo,
            $this->digester,
            $finder,
            $tenants,
            $this->createStub(DcrInitialAccessTokenCommandRepositoryGateway::class),
        );
    }

    protected function tearDown(): void
    {
        foreach ($this->created as $uid) {
            $this->pdo->prepare('DELETE FROM access_dcr_initial_access_token WHERE uid = :uid')->execute(['uid' => $uid]);
        }
    }

    public function testValidTokenIsConsumedOnceAndHandsItsGrants(): void
    {
        $uid = $this->insert('valid-token', allowedGrantTypes: '["client_credentials"]');
        $seen = null;

        self::assertTrue($this->adapter->consume('mine', 'valid-token', function (DcrInitialAccess $access) use (&$seen): void {
            $seen = $access;
        }));
        self::assertSame($uid, $seen?->uid);
        self::assertSame(['client_credentials'], $seen?->allowedGrantTypes);
        self::assertSame(1, $this->uses($uid));
        self::assertFalse($this->consume('valid-token'), 'max_uses = 1 is exhausted');
    }

    public function testTokenAllowsAsManyRegistrationsAsMaxUses(): void
    {
        $uid = $this->insert('multi-token', maxUses: 2);

        self::assertTrue($this->consume('multi-token'));
        self::assertTrue($this->consume('multi-token'));
        self::assertFalse($this->consume('multi-token'));
        self::assertSame(2, $this->uses($uid));
    }

    public function testEmptyAndUnknownTokensAreRejected(): void
    {
        $this->insert('real-token');

        self::assertFalse($this->consume(''));
        self::assertFalse($this->consume('made-up-token'));
    }

    public function testExpiredTokenIsRejected(): void
    {
        $this->insert('expired-token', expiresAt: '-1 minute');

        self::assertFalse($this->consume('expired-token'));
    }

    public function testRevokedTokenIsRejected(): void
    {
        $this->insert('revoked-token', revoked: true);

        self::assertFalse($this->consume('revoked-token'));
    }

    public function testTokenOfAnotherTenantIsRejected(): void
    {
        $uid = $this->insert('tenant-token');

        self::assertFalse($this->adapter->consume('other', 'tenant-token', static function (): void {
        }));
        self::assertFalse($this->adapter->consume('unknown', 'tenant-token', static function (): void {
        }));
        self::assertSame(0, $this->uses($uid));
    }

    public function testRejectedRegistrationDoesNotSpendTheUse(): void
    {
        $uid = $this->insert('kept-token');

        try {
            $this->adapter->consume('mine', 'kept-token', static function (): void {
                throw DynamicClientException::invalidClientMetadata('bad metadata');
            });
            $this->fail('The validation error must propagate');
        } catch (DynamicClientException) {
        }

        self::assertSame(0, $this->uses($uid));
        self::assertTrue($this->consume('kept-token'));
    }

    private function consume(string $token): bool
    {
        return $this->adapter->consume('mine', $token, static function (): void {
        });
    }

    private function insert(string $token, int $maxUses = 1, string $expiresAt = '+1 hour', bool $revoked = false, ?string $allowedGrantTypes = null): string
    {
        $uid = 'iat-test-' . bin2hex(random_bytes(6));
        $this->pdo->prepare(
            'INSERT INTO access_dcr_initial_access_token (uid, version, tenant, token_hash, expires_at, max_uses, uses, allowed_grant_types, revoked_at)'
            . ' VALUES (:uid, 0, :tenant, :hash, :expires, :max, 0, :grants, :revoked)'
        )->execute([
            'uid' => $uid,
            'tenant' => $this->tenantUid,
            'hash' => $this->digester->digest($token),
            'expires' => (new \DateTimeImmutable($expiresAt))->format('Y-m-d H:i:s'),
            'max' => $maxUses,
            'grants' => $allowedGrantTypes,
            'revoked' => $revoked ? (new \DateTimeImmutable('-1 minute'))->format('Y-m-d H:i:s') : null,
        ]);
        $this->created[] = $uid;
        return $uid;
    }

    private function uses(string $uid): int
    {
        $stmt = $this->pdo->prepare('SELECT uses FROM access_dcr_initial_access_token WHERE uid = :uid');
        $stmt->execute(['uid' => $uid]);
        return (int) $stmt->fetchColumn();
    }

    private function connect(): PDO
    {
        $config = new AppConfig();
        $dsn = $config->get('database.url');
        if (!is_string($dsn) || !str_starts_with($dsn, 'mysql:')) {
            $this->markTestSkipped('MySQL integration database not configured');
        }
        try {
            return new PDO($dsn, $config->get('database.username'), $config->get('database.password'), [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            ]);
        } catch (\PDOException) {
            $this->markTestSkipped('MySQL integration database not available');
        }
    }
}
